const handleSearch = async () => {
  if (!searchForm.keyword.trim()) {
    ElMessage.warning('请输入搜索关键词')
    return
  }
  hasSearched.value = true
  showRecommendations.value = false
  searchError.value = ''
  loading.value = true
  try {
    const res = await searchPapers(buildSearchParams())
    if (res.code === '200') {
      const data = res.data
      if (data && data.data) {
        papers.value = data.data
        total.value = data.total || 0
      } else if (Array.isArray(data)) {
        papers.value = data
        total.value = data.length
      } else {
        papers.value = []
        total.value = 0
      }
      await loadVisibleMarks()
    } else {
      papers.value = []
      total.value = 0
      searchError.value = res.msg || '暂时无法完成检索，请稍后重试。'
    }
  } catch (error) {
    papers.value = []
    total.value = 0
    searchError.value = error.code === 'ECONNABORTED'
      ? '检索请求超时，请稍后重试或切换论文来源。'
      : (error.response?.data?.msg || '网络连接失败，请检查网络后重新搜索。')
  } finally {
    loading.value = false
  }
}

